import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { smallFeature, smallFeatureFiles } from "../../application/testing/index.ts";
import { type FileChange, FileChange as FileChangeSchema, parseUnifiedDiff } from "./index.ts";

// Real `git diff` output, regenerated by scripts/make-diff-fixtures.sh.
const fixture = (name: string): string =>
  readFileSync(new URL(`fixtures/${name}.diff`, import.meta.url), "utf8");

const parse = (diff: string): FileChange[] => {
  const result = parseUnifiedDiff(diff);
  if (!result.ok) throw new Error(`line ${result.error.line}: ${result.error.message}`);
  for (const file of result.value) expect(FileChangeSchema.parse(file)).toEqual(file);
  return result.value;
};

const parseOne = (name: string): FileChange => {
  const files = parse(fixture(name));
  expect(files).toHaveLength(1);
  const [file] = files;
  if (file === undefined) throw new Error("no file");
  return file;
};

const errorOf = (diff: string) => {
  const result = parseUnifiedDiff(diff);
  if (result.ok) throw new Error("expected a parse error");
  return result.error;
};

/** Each line as git prints it, for compact expectations. */
const printed = (file: FileChange): string[] =>
  file.hunks.flatMap((hunk) =>
    hunk.lines.map(
      (line) =>
        `${{ context: " ", add: "+", del: "-" }[line.kind]}${line.text}` +
        `|${line.oldLine ?? ""},${line.newLine ?? ""}${line.noNewlineAtEnd ? "|eof" : ""}`,
    ),
  );

describe("parseUnifiedDiff", () => {
  it("parses an empty diff", () => {
    expect(parseUnifiedDiff("")).toEqual({ ok: true, value: [] });
  });

  it("parses an added file", () => {
    const file = parseOne("added");
    expect(file).toMatchObject({
      path: "notes.txt",
      oldPath: null,
      status: "added",
      binary: false,
      oldMode: null,
      newMode: null,
      language: null,
      additions: 5,
      deletions: 0,
    });
    expect(file.hunks).toHaveLength(1);
    expect(file.hunks[0]).toMatchObject({
      path: "notes.txt",
      oldStart: 0,
      oldLines: 0,
      newStart: 1,
      newLines: 5,
      sectionHeading: null,
    });
    expect(printed(file)).toEqual([
      "+line 1|,1",
      "+line 2|,2",
      "+line 3|,3",
      "+line 4|,4",
      "+line 5|,5",
    ]);
  });

  it("parses a deleted file under its old path", () => {
    const file = parseOne("deleted");
    expect(file).toMatchObject({
      path: "notes.txt",
      status: "deleted",
      additions: 0,
      deletions: 5,
    });
    expect(printed(file).at(-1)).toBe("-line 5|5,");
  });

  it("numbers old and new lines of a modified file", () => {
    const file = parseOne("modified");
    expect(file).toMatchObject({ status: "modified", additions: 1, deletions: 1 });
    expect(file.hunks[0]?.sectionHeading).toBe("line 1");
    expect(printed(file)).toEqual([
      " line 2|2,2",
      " line 3|3,3",
      " line 4|4,4",
      "-line 5|5,",
      "+line five|,5",
      " line 6|6,6",
      " line 7|7,7",
      " line 8|8,8",
    ]);
  });

  it("parses a pure rename with no hunks", () => {
    expect(parseOne("renamed")).toMatchObject({
      path: "new.txt",
      oldPath: "old.txt",
      status: "renamed",
      hunks: [],
      additions: 0,
      deletions: 0,
    });
  });

  it("parses a rename with changes", () => {
    const file = parseOne("renamed-modified");
    expect(file).toMatchObject({ path: "new.txt", oldPath: "old.txt", status: "renamed" });
    expect(file.hunks.map((hunk) => hunk.path)).toEqual(["new.txt"]);
    expect(file.additions + file.deletions).toBe(2);
  });

  it("treats a copy as an added file at the new path", () => {
    expect(parseOne("copied")).toMatchObject({
      path: "copy.txt",
      oldPath: null,
      status: "added",
      hunks: [],
    });
  });

  it.each(["binary", "binary-patch"])("marks %s files as binary, with no hunks", (name) => {
    expect(parseOne(name)).toMatchObject({
      path: "pixel.gif",
      status: "added",
      binary: true,
      hunks: [],
    });
  });

  it("keeps parsing after a binary patch", () => {
    const files = parse(`${fixture("binary-patch")}${fixture("added")}`);
    expect(files.map((file) => file.path)).toEqual(["pixel.gif", "notes.txt"]);
  });

  it("records a mode change with no hunks as a modified file", () => {
    expect(parseOne("mode-only")).toMatchObject({
      path: "run.sh",
      status: "modified",
      oldMode: "100644",
      newMode: "100755",
      hunks: [],
    });
  });

  it("parses an added empty file", () => {
    expect(parseOne("empty-file-added")).toMatchObject({
      path: "empty.txt",
      status: "added",
      hunks: [],
    });
  });

  it.each([
    ["no-newline-old", ["-two|2,|eof", "+two|,2"]],
    ["no-newline-new", ["-two|2,", "+two|,2|eof"]],
    ["no-newline-both", ["-two|2,|eof", "+three|,2|eof"]],
  ])("marks the line before a missing final newline (%s)", (name, changed) => {
    expect(printed(parseOne(name))).toEqual([" one|1,1", ...changed]);
  });

  it("keeps carriage returns in line text", () => {
    expect(parseOne("crlf").hunks[0]?.lines.map((line) => line.text)).toEqual([
      "one\r",
      "two\r",
      "two",
      "three\r",
    ]);
  });

  it("unquotes paths with tabs and non-ASCII characters", () => {
    expect(parseOne("quoted-path").path).toBe("dir with space/with space\tand é.txt");
  });

  it("reads unquoted paths with spaces, dropping git's trailing tab", () => {
    expect(parseOne("spaced-path").path).toBe("dir with space/plain name.txt");
  });

  it("reads quoted paths in rename and diff --git lines", () => {
    const diff = [
      'diff --git "a/caf\\303\\251.txt" "b/th\\303\\251.txt"',
      "similarity index 100%",
      'rename from "caf\\303\\251.txt"',
      'rename to "th\\303\\251.txt"',
      "",
    ].join("\n");
    expect(parse(diff)).toMatchObject([{ path: "thé.txt", oldPath: "café.txt" }]);
  });

  it("parses several hunks with section headings", () => {
    const file = parseOne("multiple-hunks");
    expect(
      file.hunks.map((h) => [h.oldStart, h.oldLines, h.newStart, h.newLines, h.sectionHeading]),
    ).toEqual([
      [2, 7, 2, 7, null],
      [14, 6, 14, 6, "double circumference(double r)"],
    ]);
    expect(file).toMatchObject({ additions: 2, deletions: 2 });
  });

  it("reads a hunk header without counts as one line", () => {
    const file = parseOne("no-counts");
    expect(file.hunks[0]).toMatchObject({ oldStart: 1, oldLines: 1, newStart: 1, newLines: 1 });
    expect(printed(file)).toEqual(["-only|1,", "+changed|,1"]);
  });

  it("parses a 2,000-line hunk", () => {
    const file = parseOne("large-hunk");
    expect(file.hunks).toHaveLength(1);
    expect(file.hunks[0]?.lines).toHaveLength(2000);
    expect(file).toMatchObject({ additions: 1000, deletions: 1000 });
    expect(printed(file).at(-1)).toBe("+row 1000|,1000");
  });

  it("parses many files in order", () => {
    const names = ["added", "deleted", "renamed", "mode-only", "binary", "multiple-hunks"];
    const files = parse(names.map(fixture).join(""));
    expect(files.map((file) => file.status)).toEqual([
      "added",
      "deleted",
      "renamed",
      "modified",
      "added",
      "modified",
    ]);
  });

  it("parses a diff whose last line has no newline", () => {
    expect(parse(fixture("modified").trimEnd())[0]?.additions).toBe(1);
  });

  it("parses the small-feature fixture into its expected file changes", () => {
    const expected = smallFeatureFiles.map((file) => ({ ...file, language: null }));
    expect(parse(smallFeature.pullRequest.diff)).toEqual(expected);
  });

  describe("rejects malformed input", () => {
    const modified = fixture("modified");

    it.each([
      ["more old lines", "@@ -2,7 +2,7 @@", "@@ -2,8 +2,7 @@", "fewer lines than its header says"],
      ["fewer old lines", "@@ -2,7 +2,7 @@", "@@ -2,6 +2,7 @@", "more lines than its header says"],
      ["more new lines", "@@ -2,7 +2,7 @@", "@@ -2,7 +2,9 @@", "fewer lines than its header says"],
      ["fewer new lines", "@@ -2,7 +2,7 @@", "@@ -2,7 +2,6 @@", "more lines than its header says"],
      ["fewer of both", "@@ -2,7 +2,7 @@", "@@ -2,6 +2,6 @@", "more lines than its header says"],
      ["a bad header", "@@ -2,7 +2,7 @@", "@@ -2,7 +x @@", "bad hunk header"],
      ["a header from line 0", "@@ -2,7 +2,7 @@", "@@ -0,7 +2,7 @@", "starts at line 0"],
    ])("header counts that don't match: %s", (_, from, to, message) => {
      expect(errorOf(modified.replace(from, to)).message).toContain(message);
    });

    it("reports the line of the problem", () => {
      expect(errorOf(modified.replace("@@ -2,7 +2,7 @@", "@@ -2,7 +2,6 @@"))).toEqual({
        line: 13,
        message: "hunk has more lines than its header says",
      });
    });

    it("garbage between files", () => {
      const diff = `${fixture("added")}this is not a diff line\n${fixture("deleted")}`;
      expect(errorOf(diff)).toEqual({
        line: 12,
        message: 'expected "diff --git", found "this is not a diff line"',
      });
    });

    it("garbage before the first file", () => {
      expect(errorOf(`From: someone\n${modified}`).line).toBe(1);
    });

    it("an empty line inside a hunk", () => {
      expect(errorOf(modified.replace(" line 3\n", "\n")).message).toContain("fewer lines");
    });

    it("an unknown file header line", () => {
      expect(errorOf(modified.replace("index ", "checksum ")).message).toContain(
        "unexpected line in a file header",
      );
    });

    it("a hunk without --- and +++ lines", () => {
      const diff = modified.replace("--- a/notes.txt\n+++ b/notes.txt\n", "");
      expect(errorOf(diff).message).toContain('before the "---" and "+++"');
    });

    it.each([
      ["--- a/notes.txt", "--- notes.txt"],
      ["+++ b/notes.txt", "+++ a/notes.txt"],
      ["+++ b/notes.txt", '+++ "b/unterminated'],
    ])("a bad path: %s → %s", (from, to) => {
      expect(errorOf(modified.replace(from, to)).message).toContain("bad path");
    });

    it.each([
      ["rename from old.txt", 'rename from "bad\\q"'],
      ["rename to new.txt", 'rename to "bad\\q"'],
    ])("a bad rename path: %s", (from, to) => {
      expect(errorOf(fixture("renamed").replace(from, to)).message).toContain("bad path");
    });

    it("a bad copy path", () => {
      expect(errorOf(fixture("copied").replace("copy to copy.txt", 'copy to "')).message).toContain(
        "bad path",
      );
    });

    it("a no-newline marker before any line", () => {
      const diff = modified.replace(" line 2\n", "\\ No newline at end of file\n line 2\n");
      expect(errorOf(diff).message).toContain("before any line");
    });

    it("a file whose path can't be told", () => {
      const diff = "diff --git a/x b/y b/z\nold mode 100644\nnew mode 100755\n";
      expect(errorOf(diff)).toEqual({ line: 1, message: "can't tell the file's path" });
    });

    it("a hunk cut short at the end of the diff", () => {
      expect(errorOf(modified.split("\n").slice(0, -3).join("\n")).message).toContain(
        "fewer lines",
      );
    });
  });
});
